export const tiers=['P1','P2','P3'];
export const defaults={week:'2026-09-07',tier:'ALL',region:'ALL',status:'ALL',query:'',currency:'CNY_REFERENCE',sort:'recent'};
export function weekOf(date){const d=new Date(`${date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
export function weekEnd(start){const d=new Date(`${start}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+6);return d.toISOString().slice(0,10)}
export function filterEvents(rows,f){const q=(f.query||'').trim().toLocaleLowerCase();return rows.filter(e=>(f.week==='ALL'||(e.week||weekOf(e.date))===f.week)&&(f.tier==='ALL'||e.tier===f.tier)&&(f.region==='ALL'||e.region===f.region)&&(f.status==='ALL'||e.status===f.status)&&`${e.company} ${e.sector} ${e.summary} ${e.investors.join(' ')}`.toLocaleLowerCase().includes(q)).sort((a,b)=>f.sort==='company'?a.company.localeCompare(b.company,'zh-CN'):(b.date||b.week).localeCompare(a.date||a.week)||a.id.localeCompare(b.id));}
export function eligibleForRanking(e,currency){return ['confirmed','provided'].includes(e.status)&&e.completed!==false&&e.dealType==='equity'&&e.amountKind==='exact'&&Number.isFinite(e.amount)&&e.amount>0&&e.currency===currency;}
export function rankEvents(rows,currency){if(currency==='CNY_REFERENCE')return rows.filter(e=>e.curatedRanking?.cnyAmount&&e.region==='CHINA').sort((a,b)=>b.curatedRanking.cnyAmount-a.curatedRanking.cnyAmount||a.curatedRanking.rank-b.curatedRanking.rank).slice(0,10);return rows.filter(e=>eligibleForRanking(e,currency)).sort((a,b)=>b.amount-a.amount||(b.date||b.week).localeCompare(a.date||a.week)||a.id.localeCompare(b.id)).slice(0,10);}
export function countStats(rows){return {total:rows.length,confirmed:rows.filter(e=>e.status==='confirmed').length,disclosed:rows.filter(e=>e.amountDisclosed??(Number.isFinite(e.amount)&&e.amount>0&&e.dealType==='equity')).length,china:rows.filter(e=>e.region==='CHINA').length,pending:rows.filter(e=>['pending','provided'].includes(e.status)).length,provided:rows.filter(e=>e.status==='provided').length};}
export function csvCell(value){let text=String(value??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
export function toCsv(rows){const header=['公司','公告日期','层级','地域','轮次','原始金额','币种','核验状态','投资方','来源'];return '\uFEFF'+[header,...rows.map(e=>[e.company,e.date,e.tier,e.region,e.round,e.amountText,e.currency,e.status,e.investors.join('、'),e.sourceUrl])].map(row=>row.map(csvCell).join(',')).join('\r\n')}
export function validateEvent(e){if(!e||typeof e!=='object')throw Error('事件必须为对象');for(const field of ['id','company','sector','round','summary','sourceTitle','sourceUrl','note','amountText'])if(typeof e[field]!=='string'||!e[field].trim())throw Error(`缺少字段 ${field}`);if(e.date!==null&&(!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!Number.isFinite(Date.parse(e.date))||new Date(e.date).toISOString().slice(0,10)!==e.date))throw Error('日期无效');if(!tiers.includes(e.tier)||!['CHINA','OVERSEAS','UNKNOWN'].includes(e.region)||!['confirmed','pending','conflicting','provided'].includes(e.status)||!['A','B','C','D','UNRATED'].includes(e.grade))throw Error('分类值无效');if(!['equity','acquisition','debt','grant','ipo'].includes(e.dealType)||!['exact','lower-bound','range','unknown'].includes(e.amountKind))throw Error('金额口径无效');if(!['USD','EUR','CNY','HKD',null].includes(e.currency))throw Error('币种无效');if(e.amount!==null&&(!Number.isFinite(e.amount)||e.amount<=0))throw Error('金额无效');if(e.amountKind==='unknown'&&e.amount!==null||e.amountKind!=='unknown'&&e.amount===null)throw Error('金额与口径不一致');if(!Array.isArray(e.investors)||e.investors.some(v=>typeof v!=='string'))throw Error('投资方无效');const url=new URL(e.sourceUrl);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error('来源必须为无凭据的 HTTP(S) 链接');return e;}
export function validateDataset(rows){if(!Array.isArray(rows))throw Error('数据必须为数组');rows.forEach(validateEvent);if(new Set(rows.map(e=>e.id)).size!==rows.length)throw Error('事件 ID 重复');return rows;}
